SELECT id, account_id, amount, txn_type, txn_time, RANK() OVER (PARTITION BY account_id ORDER BY amount DESC) AS rnk, ROUND(AVG(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), 2) AS amount_moving_avg_4 FROM transactions WHERE txn_time < '2024-12-21';
